<?php
require_once '../config/database.php';session_start();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$st=$pdo->prepare("SELECT * FROM admins WHERE username=? OR email=? LIMIT 1");$st->execute([$_POST['login'],$_POST['login']]);$a=$st->fetch();if($a&&password_verify($_POST['password'],$a['password_hash'])){$_SESSION['admin_id']=$a['id'];$_SESSION['admin_name']=$a['name'];header('Location: index.php');exit;}$error='Invalid login.';}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Login</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#071b34}.box{max-width:430px;margin:10vh auto;background:#fff;border-radius:18px;padding:35px}</style></head><body><div class="box"><h2>Admin Login</h2><p class="text-muted">Electronics Store</p><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><input name="login" class="form-control mb-3" placeholder="Username or email" required><input type="password" name="password" class="form-control mb-3" placeholder="Password" required><button class="btn btn-primary w-100">Login</button></form></div></body></html>